// The fonts this frame has, a page of them at a time, each name in its own
// face, and a specimen of the one picked: a big "Aa", a pangram at three
// sizes, the alphabet, figures, accents, Greek and Cyrillic. "Get fonts" adds
// more from a catalog, downloaded by the frame itself.
//
// The fonts are the files in the frame's fonts folder (frameos.listAssets):
// on a Pi what a deploy copied there, on an ESP32 its SD card, where "Sync
// fonts" puts FrameOS's collection and every TrueType file is read where it
// lies, a page at a time (docs/esp32-fonts.md), so a page of a dozen faces
// costs the frame next to nothing. In the browser preview there are none but
// the built-in face. A face is named in the classes by its file
// (`font-[Galindo-Regular.ttf]`), which every runtime finds as it finds a
// family (`font-[Galindo]`), the moment the file is there.
//
// The catalog (the public `catalog` field; FrameOS's is repo/fonts/catalog.txt)
// is a family a line: Google Fonts' TrueType files and FrameOS's own. A
// family's files come straight from where they are into the fonts folder, a
// range of bytes a request (64 KB on an ESP32, so no file is ever a string in
// its memory) and a few requests a render, the renders following each other
// until it is done: the progress shows on a fast screen, e-paper refreshes
// once with the font. The download is the private `getting` field, so one a
// restart cut short goes on.
//
// The font picked is the public `font` field (pick it here, or in the scene's
// settings); the rest of where you are is private.

const LIST_MS = 60 * 1000
const PANGRAM = 'Sphinx of black quartz, judge my vow.'
const LINES = [
  'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
  'abcdefghijklmnopqrstuvwxyz',
  '0123456789 &@#%?!()[]{}*+=/',
  'ÀÉÎÕÜ àéîõü ßçñ øå œæ ¿¡ €£',
  'Ελληνικά: Ωμέγα, άλφα, βήτα',
  'Кириллица: Жизнь, щука, ёж',
]
const KINDS = ['Sans Serif', 'Serif', 'Display', 'Handwriting', 'Monospace', 'Emoji'] // in this order
const CHECK = 'M21,7L9,19L3.5,13.5L4.91,12.09L9,16.17L19.59,5.59L21,7Z'

let listed = { at: 0, names: [] }
let tries = 0 // the catalog asked for again
let parsed = { text: null, entries: [], kinds: [] }
let confirming = ''

// The fonts folder's own files, by name.
function here() {
  if (listed.at && Date.now() - listed.at < LIST_MS) return listed.names
  const names = []
  for (const path of frameos.listAssets('fonts', { shallow: true }) || []) {
    const name = path.replace(/^fonts\//, '')
    if (name && !name.startsWith('.') && !name.includes('/')) names.push(name)
  }
  listed = { at: Date.now(), names }
  return names
}

// The font files, the built-in face ("") first, less the one coming in.
// Colour emoji fonts are bitmaps with no letters to show.
function fontsOf(coming) {
  const files = here().filter((n) => /\.ttf$/i.test(n) && !/emoji/i.test(n) && n !== coming)
  files.sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
  return [''].concat(files)
}

// "CormorantGaramond-BoldItalic.ttf" -> "Cormorant Garamond Bold Italic".
const words = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
function label(file) {
  if (!file) return 'Ubuntu (built in)'
  return file
    .replace(/\.ttf$/i, '')
    .split(/[-_]/)
    .map(words)
    .join(' ')
}

// The classes that draw in a face: the file's own name, its spaces as
// underscores (a class has none).
const faceOf = (file) => (file ? `font-[${file.replace(/ /g, '_')}]` : '')

const sizeText = (n) => (n < 1048576 ? `${Math.max(1, Math.round(n / 1024))} KB` : `${(n / 1048576).toFixed(1)} MB`)

// The catalog's families, a line each: its name and kind, the line, and the
// address its files are under (the "base" line above it); and the kinds.
function catalogOf(text) {
  if (parsed.text === text) return parsed
  const entries = []
  const kinds = []
  let base = ''
  for (const raw of text.split('\n')) {
    const line = raw.trim()
    if (!line || line[0] === '#') continue
    if (line.startsWith('base ')) base = line.slice(5).trim()
    else if (line.includes('\t')) {
      const [name, kind] = line.split('\t', 2)
      entries.push({ name, kind, base, line })
      if (kind && !kinds.includes(kind)) kinds.push(kind)
    }
  }
  kinds.sort((a, b) => (KINDS.indexOf(a) + 1 || 99) - (KINDS.indexOf(b) + 1 || 99))
  parsed = { text, entries, kinds }
  return parsed
}

// A family: its license and files ("Style address bytes [file]" each, the
// file named <Name>-<Style>.ttf unless it says).
function familyOf(entry) {
  const [name, kind, license, ...styles] = entry.line.split('\t')
  const stem = name.replace(/[^A-Za-z0-9]/g, '')
  const files = []
  for (const s of styles) {
    const [style, path, size, file] = s.split(' ')
    const named = file || `${stem}-${style}.ttf`
    const bytes = Number(size)
    if (!path || !(bytes > 0) || !/^[A-Za-z0-9][A-Za-z0-9 ._()+,-]*\.ttf$/i.test(named)) continue
    files.push({ style, url: /^https?:\/\//.test(path) ? path : entry.base + path, bytes, file: named })
  }
  return { name, kind: kind || '', license: license || '', files, bytes: files.reduce((n, f) => n + f.bytes, 0) }
}

function readJob(app) {
  let job = app.state.getting
  if (typeof job === 'string') {
    try {
      job = JSON.parse(job)
    } catch (e) {
      job = null
    }
  }
  return job && typeof job === 'object' && Array.isArray(job.files) ? job : null
}

// Downloads for up to budget ms: each file a range at a time, written as it
// comes. The job as it is now: done when i is past its files, `error` when it
// gave up (tried three times, at three renders).
function work(job, chunk, budget) {
  const began = Date.now()
  while (job.i < job.files.length && !job.error && Date.now() - began < budget) {
    const f = job.files[job.i]
    const path = `fonts/${f.file}`
    // A download a restart cut short goes on from what is on the card.
    if (job.at > 0 && frameos.assetSize(path) !== job.at) job = { ...job, at: 0 }
    const res = frameos.httpRequest(f.url, {
      headers: { Range: `bytes=${job.at}-${Math.min(job.at + chunk, f.bytes) - 1}` },
      base64: true,
      timeoutMs: 30000,
    })
    const whole = res && res.status === 200 // a server that sends the whole file
    if (!res || (res.status !== 206 && !whole)) {
      const why = res && res.status ? `the server answered ${res.status}` : (res && res.error) || 'no answer'
      if ((job.tries || 0) < 2) return { ...job, tries: (job.tries || 0) + 1 }
      if (job.at > 0) frameos.deleteAsset(path)
      return { ...job, error: `Could not get ${f.file}: ${why}` }
    }
    const b64 = res.bodyBase64 || ''
    const got = Math.floor((b64.length * 3) / 4) - (b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0)
    const wrote = got > 0 && (whole || job.at === 0 ? frameos.writeAsset(path, b64) : frameos.appendAsset(path, b64))
    const at = (whole ? 0 : job.at) + got
    if (!wrote || at > f.bytes || (at === f.bytes && frameos.assetSize(path) !== f.bytes)) {
      frameos.deleteAsset(path)
      return { ...job, error: wrote ? `${f.file} did not come whole` : `The frame could not write ${f.file}: is there room on its card?` }
    }
    job = at < f.bytes ? { ...job, at, tries: 0 } : { ...job, i: job.i + 1, at: 0, tries: 0 }
  }
  return job
}

function looks(app) {
  const ink = app.frame.paper === true || app.frame.color === false
  return ink
    ? {
        page: 'bg-white text-black',
        bar: 'border-b-2 border-black',
        button: 'rounded-full border-2 border-black',
        primary: 'rounded-full bg-black text-white',
        row: 'rounded-lg',
        selected: 'rounded-lg bg-black text-white',
        muted: '',
        card: 'rounded-lg border-2 border-black',
        field: 'rounded-full border-2 border-black bg-white',
        track: 'border-2 border-black',
        fill: 'bg-black',
      }
    : {
        page: 'bg-zinc-950 text-white',
        bar: 'border-b border-zinc-800',
        button: 'rounded-full bg-zinc-800 active:bg-zinc-600',
        primary: 'rounded-full bg-sky-600 active:bg-sky-500',
        row: 'rounded-lg active:bg-zinc-800',
        selected: 'rounded-lg bg-sky-600',
        muted: 'text-zinc-400',
        card: 'rounded-lg bg-zinc-900',
        field: 'rounded-full bg-zinc-800 focus:bg-zinc-700 placeholder:text-zinc-500',
        track: 'bg-zinc-800',
        fill: 'bg-sky-500',
      }
}

export function get(app, context) {
  const own = looks(app)
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  const zoom = Math.max(0.75, Math.min(2.25, Math.round((Math.min(width, height) / 480) * 4) / 4))
  const px = (n) => `${Math.round(n * zoom)}px`
  const wide = width >= 600 * zoom
  const rowHeight = Math.round(40 * zoom)
  const button = `flex items-center justify-center h-[${px(34)}] px-[${px(16)}] text-[${px(15)}] shrink-0`
  const Icon = ({ d, size }) => (
    <svg className={`w-[${size}] h-[${size}] shrink-0`} viewBox="0 0 24 24">
      <path d={d} fill="currentColor" />
    </svg>
  )

  // A download in progress goes on at every render of this scene.
  let job = readJob(app)
  if (job && !job.error && job.i < job.files.length) {
    const fast = app.frame.fast ?? !app.frame.paper
    const was = job.i
    job = work(job, app.frame.embedded ? 65536 : 1048576, fast ? 1200 : 40000)
    if (job.i > was) listed.at = 0
    if (job.i >= job.files.length) job = null
    frameos.setState('getting', job)
    if (job && !job.error) frameos.setNextSleep(fast ? 0.05 : 0.5)
  }
  const coming = job && !job.error && job.at > 0 ? job.files[job.i].file : ''

  const pager = (page, pages, text, turn) => (
    <div className={`flex items-center gap-[${px(8)}]`}>
      <div look="button" className={`${button} ${own.button}`} onClick={() => turn(-1)}>
        ‹
      </div>
      <span look="muted" className={`flex-1 text-center text-[${px(13)}] truncate ${own.muted}`}>
        {`${page + 1} / ${pages} · ${text}`}
      </span>
      <div look="button" className={`${button} ${own.button}`} onClick={() => turn(1)}>
        ›
      </div>
    </div>
  )

  if (app.state.view === 'get') {
    // Get fonts: the catalog, a kind and a search to narrow it, a family's files.
    const url = String(app.state.catalog || '').trim()
    const answer = url ? frameos.useFetch(url, { as: 'text', timeoutMs: 30000, tries }) : null
    const text = answer && answer.ok && typeof answer.data === 'string' ? answer.data : ''
    const { entries, kinds } = text ? catalogOf(text) : { entries: [], kinds: [] }
    const kind = kinds.includes(app.state.kind) ? app.state.kind : ''
    const find = String(frameos.recall('find') || '')
    const needle = find.trim().toLowerCase()
    const shown = entries.filter((e) => (!kind || e.kind === kind) && (!needle || e.name.toLowerCase().includes(needle)))
    const names = new Set(here())
    const hasFile = (f) => names.has(f.file) && f.file !== coming
    const picked = shown.find((e) => e.name === app.state.family)
    const family = picked ? familyOf(picked) : null
    const listing = wide || !family
    const perPage = Math.max(3, Math.floor((height - Math.round(170 * zoom)) / rowHeight))
    const pages = Math.max(1, Math.ceil(shown.length / perPage))
    const pageOfPicked = Math.floor(Math.max(0, shown.indexOf(picked)) / perPage)
    const asked = Number(app.state.shelf)
    const page = Math.min(pages - 1, Math.max(0, Number.isFinite(asked) && asked >= 0 ? asked : pageOfPicked))
    const turn = (by) => frameos.setState('shelf', Math.min(pages - 1, Math.max(0, page + by)))
    const getting = job && !job.error ? job : null
    const doneOf = (j) => j.files.slice(0, j.i).reduce((n, f) => n + f.bytes, 0) + j.at
    const totalOf = (j) => j.files.reduce((n, f) => n + f.bytes, 0)

    const start = (fam) => {
      const files = fam.files.filter((f) => !hasFile(f)).map(({ url, file, bytes }) => ({ url, file, bytes }))
      if (files.length) frameos.setState('getting', { name: fam.name, files, i: 0, at: 0, tries: 0 })
    }
    const stop = () => {
      const current = readJob(app)
      if (current && current.at > 0 && current.files[current.i]) frameos.deleteAsset(`fonts/${current.files[current.i].file}`)
      frameos.setState('getting', null)
    }
    const remove = (fam) => {
      for (const f of fam.files) if (names.has(f.file)) frameos.deleteAsset(`fonts/${f.file}`)
      if (fam.files.some((f) => f.file === app.state.font)) frameos.setState('font', '')
      listed.at = 0
      confirming = ''
      frameos.setState('family', fam.name)
    }
    const show = (file) => {
      frameos.setState('font', file)
      frameos.setState('view', '')
      frameos.setState('page', -1)
    }

    const status = (e) => {
      const fam = familyOf(e)
      const have = fam.files.filter(hasFile).length
      if (getting && getting.name === fam.name) return `${Math.floor((100 * doneOf(getting)) / Math.max(1, totalOf(getting)))}%`
      if (have && have === fam.files.length) return <Icon d={CHECK} size={px(18)} />
      if (have) return `${have} of ${fam.files.length}`
      return sizeText(fam.bytes)
    }

    const list = (
      <div className={`flex flex-col ${wide ? `w-[${Math.round(width * 0.4)}px] shrink-0` : 'flex-1'} min-w-0 gap-[${px(2)}]`}>
        {shown.slice(page * perPage, (page + 1) * perPage).map((e) => {
          const fam = familyOf(e)
          const on = family && family.name === fam.name
          const regular = fam.files[0] && hasFile(fam.files[0]) ? fam.files[0].file : ''
          return (
            <div
              look={on ? 'picked' : 'option'}
              className={`flex items-center gap-[${px(8)}] h-[${rowHeight}px] px-[${px(10)}] ${on ? own.selected : own.row}`}
              onClick={() => {
                confirming = ''
                frameos.setState('family', fam.name)
              }}
            >
              <span className={`flex-1 min-w-0 ${faceOf(regular)} text-[${px(19)}] truncate`}>{fam.name}</span>
              <span look="muted" className={`flex items-center text-[${px(13)}] shrink-0 ${on ? '' : own.muted}`}>
                {status(e)}
              </span>
            </div>
          )
        })}
        {shown.length ? null : (
          <span look="muted" className={`text-[${px(15)}] p-[${px(10)}] ${own.muted}`}>
            {!url
              ? 'No catalog is set: its address is in the scene settings.'
              : answer.loading && !text
                ? 'Loading the list of fonts…'
                : text
                  ? 'No font by that name.'
                  : `Could not load the list of fonts: ${answer.error || `the server answered ${answer.status}`}`}
          </span>
        )}
        {url && !text && !answer.loading ? (
          <div look="button" className={`${button} ${own.button}`} onClick={() => tries++}>
            Try again
          </div>
        ) : null}
        <div className="flex-1" />
        {pager(page, pages, `${shown.length} ${shown.length === 1 ? 'family' : 'families'}`, turn)}
      </div>
    )

    let detail = null
    if (family) {
      const have = family.files.filter(hasFile)
      const mine = getting && getting.name === family.name
      const face = have.length && hasFile(family.files[0]) ? faceOf(family.files[0].file) : ''
      const share = mine ? doneOf(getting) / Math.max(1, totalOf(getting)) : 0
      const trackWidth = Math.round((wide ? width * 0.6 - 60 * zoom : width - 52 * zoom) * 0.6)
      const failed = job && job.error && job.name === family.name ? job.error : ''
      const note = mine
        ? `Getting ${getting.files[getting.i].file}: ${sizeText(doneOf(getting))} of ${sizeText(totalOf(getting))}`
        : failed || (getting ? `Getting ${getting.name} first.` : have.length ? 'Tap a style to see it.' : '')
      detail = (
        <div look="card" className={`flex flex-col flex-1 min-w-0 gap-[${px(6)}] p-[${px(14)}] ${own.card} overflow-hidden`}>
          <span className={`${face} text-[${px(32)}] leading-tight truncate shrink-0`}>{family.name}</span>
          <span look="muted" className={`text-[${px(13)}] truncate shrink-0 ${own.muted}`}>
            {[family.kind, family.license, `${family.files.length} ${family.files.length === 1 ? 'style' : 'styles'}, ${sizeText(family.bytes)}`]
              .filter(Boolean)
              .join(' · ')}
          </span>
          {family.files.map((f) => (
            <div
              look="option"
              className={`flex items-center gap-[${px(8)}] h-[${px(32)}] px-[${px(6)}] shrink-0 ${own.row}`}
              onClick={hasFile(f) ? () => show(f.file) : undefined}
            >
              <span className={`flex-1 min-w-0 truncate ${hasFile(f) ? faceOf(f.file) : ''} text-[${px(18)}]`}>{words(f.style)}</span>
              <span look="muted" className={`flex items-center text-[${px(13)}] shrink-0 ${own.muted}`}>
                {hasFile(f) ? <Icon d={CHECK} size={px(18)} /> : sizeText(f.bytes)}
              </span>
            </div>
          ))}
          {mine ? (
            <div className={`flex items-center gap-[${px(10)}] shrink-0`}>
              <div className={`h-[${px(10)}] w-[${trackWidth}px] rounded-full ${own.track} overflow-hidden`}>
                <div className={`h-full w-[${Math.round(trackWidth * share)}px] ${own.fill}`} />
              </div>
              <div look="button" className={`${button} ${own.button}`} onClick={stop}>
                Stop
              </div>
            </div>
          ) : confirming === family.name ? (
            <div className={`flex items-center gap-[${px(8)}] shrink-0`}>
              <span className={`flex-1 min-w-0 text-[${px(15)}] truncate`}>{`Remove ${have.length} ${have.length === 1 ? 'file' : 'files'}?`}</span>
              <div look="button" className={`${button} ${own.button}`} onClick={() => (confirming = '')}>
                Keep
              </div>
              <div look="primary" className={`${button} ${own.primary}`} onClick={() => remove(family)}>
                Remove
              </div>
            </div>
          ) : (
            <div className={`flex items-center gap-[${px(8)}] shrink-0`}>
              {have.length < family.files.length && !getting ? (
                <div look="primary" className={`${button} ${own.primary}`} onClick={() => start(family)}>
                  {have.length ? 'Get the rest' : 'Get'}
                </div>
              ) : null}
              {have.length ? (
                <div look="button" className={`${button} ${own.button}`} onClick={() => (confirming = family.name)}>
                  Remove
                </div>
              ) : null}
            </div>
          )}
          {note ? (
            <span look="muted" className={`text-[${px(13)}] line-clamp-2 shrink-0 ${own.muted}`}>
              {note}
            </span>
          ) : null}
          {face
            ? [PANGRAM].concat(wide ? [] : LINES.slice(0, 3)).map((line) => (
                <span className={`${face} text-[${px(20)}] truncate shrink-0`}>{line}</span>
              ))
            : null}
        </div>
      )
    } else if (wide) {
      detail = (
        <div look="card" className={`flex flex-col flex-1 min-w-0 items-center justify-center p-[${px(14)}] ${own.card}`}>
          <span look="muted" className={`text-[${px(15)}] text-center ${own.muted}`}>
            {getting
              ? `Getting ${getting.name}: ${sizeText(doneOf(getting))} of ${sizeText(totalOf(getting))}`
              : 'Pick a font to get it onto this frame.'}
          </span>
        </div>
      )
    }

    return (
      <div look="page" className={`flex flex-col w-full h-full ${own.page}`}>
        <div look="bar" className={`flex items-center h-[${px(48)}] px-[${px(14)}] gap-[${px(10)}] ${own.bar}`}>
          <div
            look="button"
            className={`${button} ${own.button}`}
            onClick={() => (listing ? frameos.setState('view', '') : frameos.setState('family', ''))}
          >
            {listing ? '‹ Fonts' : '‹ Get fonts'}
          </div>
          <span className={`text-[${px(20)}] font-bold truncate`}>{listing ? 'Get fonts' : family.name}</span>
          <div className="flex-1" />
          <span look="muted" className={`text-[${px(13)}] shrink-0 ${own.muted}`}>{`${fontsOf(coming).length - 1} on this frame`}</span>
        </div>
        {listing ? (
          <div className={`flex items-center gap-[${px(8)}] px-[${px(12)}] pt-[${px(10)}]`}>
            <select
              look="field"
              className={`h-[${px(36)}] w-[${px(150)}] px-[${px(12)}] text-[${px(15)}] shrink-0 ${own.field}`}
              value={kind}
              onChange={(e) => {
                frameos.setState('kind', e.target.value)
                frameos.setState('shelf', 0)
              }}
            >
              {[''].concat(kinds).map((k) => (
                <option value={k} className={k === kind ? own.selected : own.row}>
                  {k || 'All kinds'}
                </option>
              ))}
            </select>
            <input
              look="field"
              className={`flex-1 min-w-0 h-[${px(36)}] px-[${px(14)}] text-[${px(15)}] ${own.field}`}
              value={find}
              placeholder="Search"
              onChange={(e) => {
                frameos.remember('find', e.target.value)
                frameos.setState('shelf', 0)
              }}
            />
          </div>
        ) : null}
        <div className={`flex flex-1 min-h-0 gap-[${px(14)}] p-[${px(12)}]`}>
          {listing ? list : null}
          {detail}
        </div>
      </div>
    )
  }

  const fonts = fontsOf(coming)
  const picked = typeof app.state.font === 'string' && fonts.includes(app.state.font) ? app.state.font : ''
  if (context && context.round === true) return roundFonts(app, own, width, height, zoom, fonts, picked)
  // A narrow screen shows the list or the specimen: `page` -1 is the specimen.
  const listing = wide || Number(app.state.page) >= 0
  const perPage = Math.max(3, Math.floor((height - Math.round(110 * zoom)) / rowHeight))
  const pages = Math.max(1, Math.ceil(fonts.length / perPage))
  const pageOfPicked = Math.floor(Math.max(0, fonts.indexOf(picked)) / perPage)
  const asked = Number(app.state.page)
  const page = Math.min(pages - 1, Math.max(0, Number.isFinite(asked) && asked >= 0 ? asked : pageOfPicked))
  const shown = fonts.slice(page * perPage, (page + 1) * perPage)

  const pick = (file) => {
    frameos.setState('font', file)
    if (!wide) frameos.setState('page', -1)
  }
  const turn = (by) => frameos.setState('page', Math.min(pages - 1, Math.max(0, page + by)))

  const list = (
    <div className={`flex flex-col ${wide ? `w-[${Math.round(width * 0.4)}px] shrink-0` : 'flex-1'} min-w-0 gap-[${px(2)}]`}>
      {shown.map((file) => (
        <div
          look={file === picked ? 'picked' : 'option'}
          className={`flex items-center h-[${rowHeight}px] px-[${px(10)}] ${file === picked ? own.selected : own.row}`}
          onClick={() => pick(file)}
        >
          <span className={`${faceOf(file)} text-[${px(19)}] truncate`}>{label(file)}</span>
        </div>
      ))}
      <div className="flex-1" />
      {pager(page, pages, `${fonts.length - 1} fonts`, turn)}
    </div>
  )

  const face = faceOf(picked)
  const specimen = (
    <div look="card" className={`flex flex-col flex-1 min-w-0 gap-[${px(6)}] p-[${px(14)}] ${own.card} overflow-hidden`}>
      <div className={`flex items-end gap-[${px(14)}]`}>
        <span className={`${face} text-[${px(92)}] leading-none`}>Aa</span>
        <div className="flex flex-col min-w-0 pb-[6px]">
          <span className={`text-[${px(17)}] font-bold whitespace-nowrap`}>{label(picked)}</span>
          <span look="muted" className={`text-[${px(12)}] whitespace-nowrap ${own.muted}`}>
            {picked || 'compiled into FrameOS'}
          </span>
        </div>
      </div>
      <span className={`${face} text-[${px(30)}] leading-tight`}>{PANGRAM}</span>
      <span className={`${face} text-[${px(20)}] leading-snug`}>{PANGRAM}</span>
      <span className={`${face} text-[${px(14)}]`}>{PANGRAM}</span>
      {LINES.map((line) => (
        <span className={`${face} text-[${px(18)}] truncate`}>{line}</span>
      ))}
    </div>
  )

  return (
    <div look="page" className={`flex flex-col w-full h-full ${own.page}`}>
      <div look="bar" className={`flex items-center h-[${px(48)}] px-[${px(14)}] gap-[${px(10)}] ${own.bar}`}>
        {!wide && !listing ? (
          <div look="button" className={`${button} ${own.button}`} onClick={() => frameos.setState('page', pageOfPicked)}>
            ‹ Fonts
          </div>
        ) : (
          <span className={`text-[${px(20)}] font-bold`}>Fonts</span>
        )}
        <div className="flex-1" />
        {wide ? (
          <span look="muted" className={`text-[${px(13)}] ${own.muted}`}>
            {fonts.length > 1 ? `${fonts.length - 1} on this frame` : 'only the built-in face here'}
          </span>
        ) : null}
        <div look="button" className={`${button} ${own.button}`} onClick={() => frameos.setState('view', 'get')}>
          {job && !job.error ? `Getting ${job.name}…` : 'Get fonts'}
        </div>
      </div>
      <div className={`flex flex-1 min-h-0 gap-[${px(14)}] p-[${px(12)}]`}>
        {wide || listing ? list : null}
        {wide || !listing ? specimen : null}
      </div>
    </div>
  )
}

// A round panel: the title in the arc at the top, the page's fonts as rows
// as wide as the circle is where each one is (the rows near the middle a
// little bigger), the page turns in the arc at the bottom; the specimen
// centred, its lines as wide as the circle lets them be.
function roundFonts(app, own, W, H, zoom, fonts, picked) {
  const px = (n) => `${Math.round(n * zoom)}px`
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12
  const chord = (dy) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  const place = (top, height, width, cls, child, onClick = undefined) => (
    <div className={`absolute left-[${Math.round(cx - width / 2)}px] top-[${Math.round(cy + top)}px] w-[${width}px] h-[${height}px] ${cls}`} onClick={onClick}>{child}</div>
  )
  const button = `flex items-center justify-center h-[${px(34)}] px-[${px(16)}] text-[${px(15)}]`
  const listTop = -Math.round(R * 0.62)
  const listBottom = Math.round(R * 0.56)
  const rowHeight = Math.round(40 * zoom)
  const perPage = Math.max(3, Math.floor((listBottom - listTop) / rowHeight))
  const pages = Math.max(1, Math.ceil(fonts.length / perPage))
  const pageOfPicked = Math.floor(Math.max(0, fonts.indexOf(picked)) / perPage)
  const asked = Number(app.state.page)
  const listing = asked >= 0
  const page = Math.min(pages - 1, Math.max(0, Number.isFinite(asked) && asked >= 0 ? asked : pageOfPicked))
  const shown = fonts.slice(page * perPage, (page + 1) * perPage)
  const turn = (by) => frameos.setState('page', Math.min(pages - 1, Math.max(0, page + by)))
  const pick = (file) => {
    frameos.setState('font', file)
    frameos.setState('page', -1)
  }

  if (!listing) {
    const face = faceOf(picked)
    const top = -Math.round(R * 0.66)
    const bottom = Math.round(R * 0.8)
    return (
      <div look="page" className={`relative w-[${W}px] h-[${H}px] ${own.page}`}>
        {place(-Math.round(R * 0.9), Math.round(R * 0.9) + top, chord(R * 0.9), 'flex items-center justify-center',
          <div look="button" className={`${button} ${own.button}`} onClick={() => frameos.setState('page', pageOfPicked)}>
            ‹ Fonts
          </div>)}
        {place(top, bottom - top, chord(Math.max(-top, bottom)), `flex flex-col items-center gap-[${px(6)}] overflow-hidden text-center`,
          <>
            <span className={`${face} text-[${px(80)}] leading-none shrink-0`}>Aa</span>
            <span className={`text-[${px(17)}] font-bold truncate shrink-0`}>{label(picked)}</span>
            <span className={`${face} text-[${px(24)}] leading-tight shrink-0`}>{PANGRAM}</span>
            <span className={`${face} text-[${px(16)}] leading-snug shrink-0`}>{PANGRAM}</span>
            {LINES.slice(0, 2).map((line) => (
              <span className={`${face} text-[${px(16)}] truncate shrink-0`}>{line}</span>
            ))}
          </>)}
      </div>
    )
  }

  // The rows: heights weighted toward the middle, filling the list's room.
  const weights = shown.map((_, i) => {
    const t = shown.length > 1 ? (i / (shown.length - 1)) * 2 - 1 : 0
    return 1.2 - 0.35 * Math.abs(t)
  })
  const sum = weights.reduce((a, b) => a + b, 0)
  const room = Math.min(listBottom - listTop, Math.round(rowHeight * sum))
  let y = listTop + Math.round((listBottom - listTop - room) / 2)
  const rows = shown.map((file, i) => {
    const h = Math.round((room * weights[i]) / sum)
    const top = y
    y += h
    const w = chord(Math.max(Math.abs(top), Math.abs(top + h))) - 8
    return place(top, h - 2, w, `flex items-center justify-center px-[${px(10)}] ${file === picked ? own.selected : own.row}`,
      <span className={`${faceOf(file)} text-[${Math.round(h * 0.47)}px] truncate`}>{label(file)}</span>, () => pick(file))
  })
  const turnTop = listBottom + Math.round(8 * zoom)
  return (
    <div look="page" className={`relative w-[${W}px] h-[${H}px] ${own.page}`}>
      {place(-Math.round(R * 0.92), Math.round(R * 0.92) + listTop - 4, chord(R * 0.92), 'flex flex-col items-center justify-center',
        <>
          <span className={`text-[${px(20)}] font-bold`}>Fonts</span>
          <span look="muted" className={`text-[${px(13)}] ${own.muted}`}>
            {fonts.length > 1 ? `${fonts.length - 1} on this frame` : 'only the built-in face here'}
          </span>
        </>)}
      {rows}
      {place(turnTop, Math.round(34 * zoom), chord(turnTop + 34 * zoom), `flex items-center gap-[${px(8)}]`,
        <>
          <div look="button" className={`${button} ${own.button}`} onClick={() => turn(-1)}>‹</div>
          <span look="muted" className={`flex-1 text-center text-[${px(13)}] ${own.muted}`}>{`${page + 1} / ${pages}`}</span>
          <div look="button" className={`${button} ${own.button}`} onClick={() => turn(1)}>›</div>
        </>)}
    </div>
  )
}
